// Rastrigin 30: DE/rand/1/bin of rule 6.3, with no target: every run uses the fixed budget. `De`
// with the strategy DE/rand/1, a fixed F 0.5 and
// CR 0.9 (genoxide's `Control::default()`, set explicitly), 100 individuals and no restarts. It
// starts from a uniform random population, crosses binomially with a forced gene, replaces a
// target by a trial that isn't worse, generation by generation, and sets a trial gene outside the
// box halfway between the target's gene and the bound (rule 2.4)
fn run_rastrigin(args: &Args, seed: u64) -> Result<()> {
    let bounds = -RASTRIGIN_UPPER..=RASTRIGIN_UPPER;
    let inside = |genome: &Reals| genome.iter().all(|x| bounds.contains(x));
    let build = |seed| {
        De::builder(Real::uniform(args.size, bounds.clone())?)
            .population_size(100)
            .strategy(de::Strategy::Rand1)
            .control(de::Control::Fixed { f: 0.5, cr: 0.9 })
            .restarts(de::Restarts::Never)
            .minimize()
            .seed(seed)
            .build()
    };
    solve(args, seed, "de", None, build, rastrigin, inside)
}

def solve(method, seed, counter, size, problem_name):
    """Runs the method once, until the target, the budget or the time cap, and returns why it
    ended otherwise (rules 2.2 and 8.4): the pycma criterion that ended CMAES, or None. CMAES
    also ends, with no criterion, on any error pycma raises (its _advance catches them all)."""
    function, lower, upper, _ = PROBLEMS[problem_name]
    algorithm, run_seed = method(size, seed)
    termination = BudgetTermination(counter)
    np.random.seed(run_seed)
    try:
        minimize(CountedProblem(counter, function, size, lower, upper), algorithm, termination,
                 seed=run_seed, verbose=False, copy_algorithm=False, copy_termination=False)
    except Stop:
        pass
    if counter.reached() or counter.out_of_budget():
        return None
    stopped = termination.pycma and dict(termination.pycma.stop(check=False))
    if stopped:
        return "pycma's " + ", ".join(sorted(stopped))
    return "the algorithm ended with no stop criterion (for CMAES: an error in pycma)"

static long de(Budget budget, RealProblem problem) {
    var evaluator = new CountingEvaluator(budget);
    var de = new DifferentialEvolution(problem, Integer.MAX_VALUE, 100,
        new DifferentialEvolutionCrossover(0.9, 0.5, DifferentialEvolutionCrossover.DE_VARIANT.RAND_1_BIN),
        new DifferentialEvolutionSelection(), evaluator);
    try {
        de.run();
    } catch (Stop stop) {
        // the budget or the time cap
    }
    // the generations after the initial population
    return Math.max(0, evaluator.calls - 1);
}

static final class CountingEvaluator extends SequentialSolutionListEvaluator<DoubleSolution> {
    final Budget budget;
    long calls;

    CountingEvaluator(Budget budget) {
        this.budget = budget;
    }

    @Override
    public List<DoubleSolution> evaluate(List<DoubleSolution> solutionList, Problem<DoubleSolution> problem) {
        calls++;
        budget.endGeneration();
        return super.evaluate(solutionList, problem);
    }
}
